mapper.select:
SELECT * FROM ( SELECT R.*, (SELECT MAX(rp.REG_TITLE) FROM ORDER_ITEM oi JOIN REGISTER_PROD rp ON rp.REG_ID = oi.REG_ID WHERE oi.ORDER_NO = R.ORDER_NO ) AS REG_TITLE, ROW_NUMBER() OVER (ORDER BY R.REVIEW_NO DESC) RN FROM REVIEW_BOARD R
(R.REVIEW_TITLE LIKE '%' || #{q} || '%' OR R.REVIEW_CTT LIKE '%' || #{q} || '%')
) WHERE RN BETWEEN #{startRow} AND #{endRow}

mapper.update:
UPDATE REVIEW_BOARD
  SET REVIEW_HIT = NVL(REVIEW_HIT,0) + 1
WHERE REVIEW_NO = #{reviewNo}

mapper.delete:
DELETE FROM REVIEW_BOARD
WHERE REVIEW_NO = #{reviewNo}
  AND USER_ID = #{userId}

mapper.select:
SELECT COUNT(1)
FROM ORDERS o
WHERE o.ORDER_NO = #{orderNo}
  AND o.USER_ID = #{userId}
  AND o.ORDER_STATUS IN ('PAID')

SELECT COUNT(1)
FROM REVIEW_BOARD
WHERE ORDER_NO = #{value}
